    const c = structuredClone(source?.config || state.data.defaults), p = c.parameters, capabilities = state.data.capabilities || {}, symbols = [...new Set([...(state.symbols.length ? state.symbols : ['BTC/USDT', 'ETH/USDT', 'SOL/USDT']), c.symbol])];
    openModal(shell(source ? '复制为新策略' : '新建策略实例', '配置保存在本机后端；提交训练后使用真实行情与本机计算。', `<form id="strategy-form"><div class="dialog-body"><div class="template-choice">${[['rule', '规则策略', '双均线 · 直接回测'], ['rl', 'RL 策略', 'PPO · 本机训练'], ['prediction', '预测模型', 'LightGBM · 收益率回归']].map(([value, text, desc]) => `<label><span><input type="radio" name="kind" value="${value}" ${c.kind === value ? 'checked' : ''} ${capabilities.kinds && !capabilities.kinds.includes(value) ? 'disabled' : ''}> ${text}</span><small>${desc}</small></label>`).join('')}</div><div class="form-grid"><div class="field full"><label for="strategy-name">策略名称</label><input id="strategy-name" name="name" maxlength="80" required value="${esc(source ? c.name + ' · 副本' : c.name)}"></div><div class="field"><label for="strategy-symbol">交易品种 · Binance 现货</label><input id="strategy-symbol" name="symbol" list="market-symbols" required value="${esc(c.symbol)}" placeholder="例如 SOL/USDT"><datalist id="market-symbols">${symbols.map(s => `<option value="${esc(s)}"></option>`).join('')}</datalist></div><div class="field"><label for="strategy-wallet">独立虚拟资金 · USDT</label><input id="strategy-wallet" name="wallet" type="number" min="100" max="1000000" step="any" required value="${c.wallet}"></div><div class="field"><label for="strategy-start">历史开始 · UTC</label><input id="strategy-start" name="start" type="date" min="2025-01-01" max="2025-09-17" required value="${esc(c.start)}"></div><div class="field"><label for="strategy-end">历史结束 · UTC（不含）</label><input id="strategy-end" name="end" type="date" min="2025-01-15" max="2025-10-01" required value="${esc(c.end)}"></div><div class="field"><label for="strategy-stake">单次开仓金额 · USDT</label><input id="strategy-stake" name="stake" type="number" min="10" step="any" required value="${c.stake}"></div><div class="field"><label for="strategy-stop">止损阈值 · %</label><input id="strategy-stop" name="stop_loss" type="number" min="0.1" max="50" step="any" required value="${p.stop_loss * 100}"></div><div class="field" data-kind-field="rule"><label for="strategy-fast">快速均线周期</label><input id="strategy-fast" name="fast" type="number" min="2" max="64" step="1" value="${p.fast}" required></div><div class="field" data-kind-field="rule"><label for="strategy-slow">慢速均线周期</label><input id="strategy-slow" name="slow" type="number" min="3" max="128" step="1" value="${p.slow}" required></div><div class="field" data-kind-field="rl"><label for="strategy-steps">PPO 训练步数</label><select id="strategy-steps" name="rl_steps">${(capabilities.rl_steps?.values || [2048, 8192]).map(value => `<option value="${value}" ${p.rl_steps === value ? 'selected' : ''}>${value} 步${value === 2048 ? ' · 快速验证' : ' · 较充分训练'}</option>`).join('')}</select></div><div class="field" data-kind-field="rl prediction"><label for="strategy-seed">随机种子</label><input id="strategy-seed" name="seed" type="number" min="0" max="1000000" step="1" value="${p.seed}" required></div><div class="field" data-kind-field="prediction"><label for="strategy-horizon">预测期限 · 小时</label><input id="strategy-horizon" name="horizon" type="number" min="1" max="24" step="1" value="${p.horizon}" required></div><div class="field" data-kind-field="prediction"><label for="strategy-threshold">入场预测收益阈值 · %</label><input id="strategy-threshold" name="entry_threshold" type="number" min="0" max="10" step="any" value="${p.entry_threshold * 100}" required></div><div class="field"><label for="strategy-fee">单边手续费 · %</label><input id="strategy-fee" name="fee" type="number" min="0" max="1" step="any" value="${c.fee * 100}" required></div><div class="field"><label>新闻训练输入</label><input disabled value="后续接入 · 当前仅行情"></div></div><div class="hint" style="margin-top:15px">周期固定 1h；任务按时间顺序划分训练与评估。保留区间 ${(capabilities.reserved_period || []).join(' → ')} 不可用作开发训练。品种的实际可用性由后端核验。</div><div id="form-error" class="form-error hidden" role="alert"></div></div></form>`, '<button data-action="close-modal">取消</button><button class="primary" type="submit" form="strategy-form">保存并前往训练</button>'), { type: 'create', key: uid(), defaults: c });
    updateKindFields();
